import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.time.LocalDate;
import java.util.Objects;

@Service
@Transactional
public class ReturnLoanService implements ReturnLoanUseCase {

    private final LoadLoanPort loadLoanPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveAuditRecordPort saveAuditRecordPort;

    public ReturnLoanService(LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
                             LoadBookPort loadBookPort, SaveBookPort saveBookPort,
                             SaveAuditRecordPort saveAuditRecordPort) {
        this.loadLoanPort = loadLoanPort;
        this.saveLoanPort = saveLoanPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveAuditRecordPort = saveAuditRecordPort;
    }

    @Override
    public Loan returnLoan(ReturnLoanCommand command) {
        Loan loan = loadLoanPort.loadLoan(command.loanId())
                .orElseThrow(() -> new LoanNotFoundException(command.loanId()));
        Book book = loadBookPort.loadBook(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        LocalDate returnedAt = Objects.requireNonNullElseGet(command.returnedAt(), LocalDate::now);
        loan.returnOn(returnedAt);
        book.returnBook();
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        saveAuditRecordPort.saveAuditRecord(new AuditRecord(AuditAction.RETURN, loan.getId(), loan.getMemberId(), Instant.now()));
        return loan;
    }
}
