@Service
@Transactional
public class LoanBookService implements LoanBookUseCase {

    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadReservationPort loadReservationPort;
    private final SaveReservationPort saveReservationPort;
    private final CheckCreditPort checkCreditPort;
    private final SaveAuditRecordPort saveAuditRecordPort;

    public LoanBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort, LoadMemberPort loadMemberPort,
                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
                           LoadReservationPort loadReservationPort, SaveReservationPort saveReservationPort,
                           CheckCreditPort checkCreditPort, SaveAuditRecordPort saveAuditRecordPort) {
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.saveLoanPort = saveLoanPort;
        this.loadReservationPort = loadReservationPort;
        this.saveReservationPort = saveReservationPort;
        this.checkCreditPort = checkCreditPort;
        this.saveAuditRecordPort = saveAuditRecordPort;
    }

    @Override
    public Loan loanBook(LoanBookCommand command) {
        Book book = loadBookPort.loadBook(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        Member member = loadMemberPort.loadMember(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        book.ensureLoanable();
        member.ensureCanBorrow(loadLoanPort.countActiveLoansByMemberId(member.getId()));
        // 외부 신용조회는 상태를 바꾸기 전에 한다. 거절되면 예약·책 상태가 건드려지지 않는다.
        CreditCheck creditCheck = checkCreditPort.checkCredit(member.getId(), member.getName());
        LocalDate loanedAt = Objects.requireNonNullElseGet(command.loanedAt(), LocalDate::now);
        Loan loan = Loan.start(book.getId(), member.getId(), loanedAt, creditCheck);
        ReservationQueue queue = new ReservationQueue(book.getId(),
                loadReservationPort.loadWaitingReservations(book.getId()));
        queue.fulfillFor(member.getId())
                .ifPresent(saveReservationPort::saveReservation);
        book.setStatus(BookStatus.ON_LOAN);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        saveAuditRecordPort.saveAuditRecord(new AuditRecord(AuditAction.LOAN, loan.getId(), member.getId(), Instant.now()));
        return loan;
    }
}
