package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MonthlyStatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void counts_loans_by_loan_date_and_returns_by_return_date() throws Exception {
        String memberId = registerMember();

        // 2099-01 대출 & 반납, 기간 내 반납(연체 없음)
        returnLoan(loan(registerBook("Book A"), memberId, "2099-01-05"), "2099-01-10");
        // 2098-12 대출, 2099-01 반납 — 연체 3일 → 연체료 300
        returnLoan(loan(registerBook("Book B"), memberId, "2098-12-20"), "2099-01-06");
        // 2099-01 대출, 미반납
        loan(registerBook("Book C"), memberId, "2099-01-20");
        // 2099-01 대출, 2099-02 반납 — 2099-01 반납 집계에는 들어가지 않는다
        returnLoan(loan(registerBook("Book D"), memberId, "2099-01-02"), "2099-02-10");

        mockMvc.perform(get("/stats/monthly").param("year", "2099").param("month", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2099))
                .andExpect(jsonPath("$.month").value(1))
                .andExpect(jsonPath("$.loanCount").value(3))
                .andExpect(jsonPath("$.returnCount").value(2))
                .andExpect(jsonPath("$.overdueCount").value(1))
                .andExpect(jsonPath("$.lateFeeTotal").value(300));
    }

    @Test
    void month_without_activity_returns_zeros() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2099").param("month", "6"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void invalid_month_returns_bad_request() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2099").param("month", "13"))
                .andExpect(status().isBadRequest());
    }

    private String loan(String bookId, String memberId, String loanedAt) throws Exception {
        return readId(mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                                + "\",\"loanedAt\":\"" + loanedAt + "\"}")), "loanId");
    }

    private void returnLoan(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String registerMember() throws Exception {
        return readId(mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}")), "memberId");
    }

    private String registerBook(String title) throws Exception {
        return readId(mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}")), "id");
    }

    private String readId(ResultActions result, String field) throws Exception {
        String body = result.andReturn().getResponse().getContentAsString();
        JsonNode node = objectMapper.readTree(body);
        return node.get(field).asText();
    }
}

